import { spawn } from 'node:child_process';

export function build(target: string): Promise<number> {
  // eslint-disable-next-line security/detect-child-process -- target is validated against a fixed allowlist above
  const child = spawn('npm', ['run', target], { stdio: 'inherit' });
  return new Promise((resolve) => child.on('close', (code) => resolve(code ?? 1)));
}
